const b = $json.body ?? $json;

const issue = String(b.issue_description ?? '').trim();

if (!issue) {
  return [{
    json: {
      success: false,
      error: 'issue_description is required'
    }
  }];
}

const prompt = `
You are an expert facility maintenance issue analyzer.

Analyze the following maintenance request.

Return ONLY valid JSON with these keys:
{
  "category": "",
  "priority": "",
  "summary": "",
  "recommended_action": "",
  "requires_human_review": false
}

Allowed categories:
HVAC, Plumbing, Electrical, Civil,
IT Equipment, General Maintenance, Other.

Allowed priorities:
Critical, High, Medium, Low.

Rules:
1. Identify the actual maintenance category.
2. Critical incidents include fire, gas leaks,
   exposed live wires, electrocution, and structural danger.
3. Critical incidents MUST require human review.
4. Never recommend dangerous DIY repairs.
5. Recommend inspection by a qualified technician
   where necessary.
6. Do not invent information.

Maintenance issue:
${issue.slice(0, 3000)}
`;

return [{
  json: {
    success: true,
    ticket_id: b.ticket_id ?? '',
    issue_description: issue.slice(0, 3000),
    prompt
  }
}];

