const response = $json;

const text = response.candidates?.[0]?.content?.parts
  ?.map(p => p.text ?? '')
  .join('')
  .trim() ?? '';

try {
  const ai = JSON.parse(text);

  const categories = [
    'HVAC', 'Plumbing', 'Electrical', 'Civil',
    'IT Equipment', 'General Maintenance', 'Other'
  ];

  const priorities = ['Critical', 'High', 'Medium', 'Low'];

  const category = categories.includes(ai.category)
    ? ai.category : 'Other';

  const priority = priorities.includes(ai.priority)
    ? ai.priority : 'Medium';

  const requiresReview =
    priority === 'Critical' ||
    ai.requires_human_review === true ||
    ai.requires_human_review === 'true';

  const input = $('Prepare Prompt').first().json;

  return [{
    json: {
      success: true,
      ticket_id: input.ticket_id,
      category,
      priority,
      summary: String(ai.summary ?? ''),
      recommended_action: String(ai.recommended_action ?? ''),
      requires_human_review: requiresReview
    }
  }];

} catch (error) {
  return [{
    json: {
      success: false,
      error: 'Unable to parse AI response',
      raw: text.slice(0, 500)
    }
  }];
}

const input = $('Prepare Prompt').first().json;

return [{
  json: {
    candidates: [{
      content: {
        parts: [{
          text: JSON.stringify({
            category: "HVAC",
            priority: "High",
            summary: "AC cooling failure with water leakage from indoor unit.",
            recommended_action: "Assign a qualified HVAC technician to inspect the AC unit and identify the leakage source.",
            requires_human_review: false
          })
        }]
      }
    }]
  }
}];
